    pub(crate) fn startup(&mut self) {
        tracing::info!(
            "startup begin: state: {:?}, is_leader: {}, is_campaigner: {}",
            self.state,
            self.state.is_leader(&self.config.id),
            self.state.is_campaigner(&self.config.id)
        );

        // Replication can precede local flushing. A former leader may have lost entries
        // that another voter retained, so resuming its term could reuse their log ids.
        // Obtain a new term and a quorum before allowing any more proposals.
        if self.state.is_leader(&self.config.id) && self.config.enable_leader_restore {
            self.elect();
            return;
        }

        // A passive restart preserves the stored vote, without creating a leader.
        let server_state = self.state.calc_following_state(&self.config.id);
        self.state.server_state = server_state;

        tracing::info!(
            "startup done, id={}, target_state: {:?}",
            self.config.id,
            self.state.server_state
        );
    }

    /// Initialize a node by appending the first log.
