        (false, 3, false, ServerState::Learner, Vote::new_committed(2, 2)),
        (true, 5, false, ServerState::Learner, Vote::new_committed(2, 2)),
        (true, 5, true, ServerState::Candidate, Vote::new(3, 2)),
    ] {
        tracing::info!(
            restore,
            committed_index,
            retain_as_learner,
            ?expected_state,
